// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

interface AggregatorV3Interface {
    function latestAnswer() external view returns (int256);
}

contract PriceFeeds {
    // Chainlink Aggregator addresses on Polygon
    address public constant INR_USD_FEED = 0x605D5c2fBCeDb217D7987FC0951B5753069bC360;
    address public constant BTC_USD_FEED = 0xF4030086522a5bEEa4988F8cA5B36dbC97BeE88c;
    address public constant ETH_USD_FEED = 0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419;
    address public constant POL_USD_FEED = 0x7bAC85A8a13A4BcD8abb3eB7d6b4d632c5a57676;
    address public constant USDC_USD_FEED = 0x8fFfFfd4AfB6115b954Bd326cbe7B4BA576818f6;
    address public constant DAI_USD_FEED = 0xAed0c38402a5d19df6E4c03F4E2DceD6e29c1ee9;
    address public constant USDT_USD_FEED = 0x3E7d1eAB13ad0104d2750B8863b489D65364e32D;
    address public constant GHO_USD_FEED = 0x3f12643D3f6f874d39C2a4c9f2Cd6f2DbAC877FC;

    function getAllRates()
        external
        view
        returns (
            int256 inrPrice,
            int256 btcPrice,
            int256 ethPrice,
            int256 maticPrice,
            int256 usdcPrice,
            int256 daiPrice,
            int256 usdtPrice,
            int256 ghoPrice
        )
    {
        inrPrice = AggregatorV3Interface(INR_USD_FEED).latestAnswer();
        btcPrice = AggregatorV3Interface(BTC_USD_FEED).latestAnswer();
        ethPrice = AggregatorV3Interface(ETH_USD_FEED).latestAnswer();
        maticPrice = AggregatorV3Interface(POL_USD_FEED).latestAnswer();
        usdcPrice = AggregatorV3Interface(USDC_USD_FEED).latestAnswer();
        daiPrice = AggregatorV3Interface(DAI_USD_FEED).latestAnswer();
        usdtPrice = AggregatorV3Interface(USDT_USD_FEED).latestAnswer();
        ghoPrice = AggregatorV3Interface(GHO_USD_FEED).latestAnswer();

        return (inrPrice, btcPrice, ethPrice, maticPrice, usdcPrice, daiPrice, usdtPrice, ghoPrice);
    }
}
